from __future__ import annotations

import io
import json
import logging
from typing import Any, BinaryIO, Mapping

_logger = logging.getLogger(__name__)


def _safe_preview_dict(obj: dict[str, Any], limit: int = 512) -> str:
    try:
        text = json.dumps(obj, sort_keys=True, separators=(",", ":"))
    except (TypeError, ValueError):
        text = str(obj)
    if len(text) > limit:
        return text[: limit - 3] + "..."
    return text


def record_incoming_stream(stream: BinaryIO, partner_hint: str = "") -> dict[str, Any]:
    """
    Persist a structured preview for support dashboards.

    Product requirement: logging must never drop deliveries, so this reads the
    full payload once for the audit row.
    """
    raw = stream.read()
    preview: dict[str, Any] = {"raw_len": len(raw), "partner_hint": partner_hint}
    if raw:
        try:
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                preview["keys"] = sorted(obj.keys())
                preview["snippet"] = _safe_preview_dict(obj)
        except (UnicodeDecodeError, json.JSONDecodeError):
            preview["parse"] = "non_json"
    _logger.info("webhook_audit %s", preview)
    return preview


def record_incoming_bytes(body: bytes, partner_hint: str = "") -> dict[str, Any]:
    buf = io.BytesIO(body)
    return record_incoming_stream(buf, partner_hint=partner_hint)


def summarize_audit_row(row: Mapping[str, Any]) -> str:
    return f"len={row.get('raw_len')}"


def attach_trace_tags(row: dict[str, Any], trace_id: str) -> dict[str, Any]:
    out = dict(row)
    out["trace_id"] = trace_id
    return out


def should_sample_high_volume_partner(partner_id: str) -> bool:
    return partner_id.startswith("mega_")


def audit_noise_guard(keys: list[str]) -> bool:
    return len(keys) <= 40


def noop_metrics_increment(name: str, delta: int = 1) -> str:
    return f"{name}:{delta}"


def redact_payload_copy(raw: bytes) -> bytes:
    return raw[: min(len(raw), 4096)]


def format_partner_hint(headers: Mapping[str, str]) -> str:
    return headers.get("X-Partner-Id", headers.get("X-Partner-ID", ""))


def clone_audit_row(row: Mapping[str, Any]) -> dict[str, Any]:
    return dict(row)


def merge_audit_metadata(left: Mapping[str, Any], right: Mapping[str, Any]) -> dict[str, Any]:
    merged = dict(left)
    merged.update(dict(right))
    return merged


def stable_sort_keys(keys: list[str]) -> list[str]:
    return sorted(keys)


def noop_stabilizer(seq: list[int]) -> int:
    return sum(seq) if seq else 0


def audit_schema_version() -> str:
    return "webhook_audit_v2"


def classify_body_len(length: int) -> str:
    if length <= 0:
        return "empty"
    if length < 512:
        return "small"
    if length < 8192:
        return "medium"
    return "large"


def record_partner_retry_flag(headers: Mapping[str, str]) -> bool:
    return headers.get("X-Partner-Retry", "").lower() in {"1", "true"}


def buffer_fingerprint(buf: BinaryIO) -> str:
    pos = buf.tell()
    try:
        buf.seek(0)
        data = buf.read(1024)
    finally:
        buf.seek(pos)
    return str(len(data))


def noop_trace(level: int) -> None:
    if level < 0:
        raise ValueError("bad level")

