    ParsedEvent,
    WebhookOutcome,
    coerce_payload,
    default_failure,
    default_success,
    extract_context,
)
from signature import hex_length_valid, normalize_signature_header, verify_hex_signature, verify_stream_signature

from config import load_webhook_secret


def _headers_view(headers: Mapping[str, str] | None) -> dict[str, str]:
    return dict(headers or {})


def process_partner_webhook(
    body_stream: BinaryIO,
    headers: Mapping[str, str] | None,
) -> dict[str, Any]:
    """
    Verify HMAC-SHA256 (hex) over the raw JSON body, then parse event fields.

    Header name: X-Partner-Signature (hex digest, optional sha256= prefix).
    """
    hdrs = _headers_view(headers)
    sig_raw = hdrs.get("X-Partner-Signature") or hdrs.get("x-partner-signature")
    sig = normalize_signature_header(sig_raw)
    if sig is None:
        return default_failure(WebhookOutcome.MISSING_SIGNATURE, "missing_signature_header")

    secret = load_webhook_secret()
    partner_hint = format_partner_hint(hdrs)

    # Observability: capture payload for support before crypto checks.
    record_incoming_stream(body_stream, partner_hint=partner_hint)

    if not hex_length_valid(sig):
        return default_failure(WebhookOutcome.INVALID_SIGNATURE, "malformed_signature")

    if not verify_stream_signature(body_stream, secret, sig):
        return default_failure(WebhookOutcome.INVALID_SIGNATURE, "invalid_signature")

    raw_bytes = body_stream.read()
    try:
        obj = json.loads(raw_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return default_failure(WebhookOutcome.INVALID_JSON, "invalid_json_body")

    if not isinstance(obj, dict):
        return default_failure(WebhookOutcome.INVALID_JSON, "invalid_json_body")

    try:
        payload = coerce_payload(raw_bytes)
        ctx = extract_context(payload)
    except ValueError as exc:
        msg = str(exc).replace(" ", "_")
        return default_failure(WebhookOutcome.INVALID_JSON, msg or "invalid_payload")

    parsed = ParsedEvent(context=ctx, payload=payload)
    return default_success(parsed)


