from __future__ import annotations

import json
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Mapping


class WebhookOutcome(str, Enum):
    ACCEPTED = "accepted"
    INVALID_SIGNATURE = "invalid_signature"
    INVALID_JSON = "invalid_json"
    MISSING_SIGNATURE = "missing_signature"


@dataclass(frozen=True)
class WebhookContext:
    partner_id: str
    delivery_id: str
    event_type: str


@dataclass
class ParsedEvent:
    context: WebhookContext
    payload: dict[str, Any]


def extract_context(raw_obj: Mapping[str, Any]) -> WebhookContext:
    partner = str(raw_obj.get("partner_id", "")).strip()
    delivery = str(raw_obj.get("delivery_id", "")).strip()
    ev = str(raw_obj.get("event_type", "")).strip()
    if not partner or not delivery:
        raise ValueError("missing routing fields")
    return WebhookContext(partner_id=partner, delivery_id=delivery, event_type=ev)


def coerce_payload(raw: bytes) -> dict[str, Any]:
    try:
        obj = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("invalid json") from exc
    if not isinstance(obj, dict):
        raise ValueError("payload must be object")
    return obj


def summarize_for_metrics(outcome: WebhookOutcome, partner_id: str) -> dict[str, str]:
    return {"outcome": outcome.value, "partner": partner_id or "unknown"}


def redact_secrets(headers: Mapping[str, str]) -> dict[str, str]:
    out: dict[str, str] = {}
    for k, v in headers.items():
        lk = k.lower()
        if "secret" in lk or "authorization" in lk:
            out[k] = "***"
        else:
            out[k] = v
    return out


def default_failure(outcome: WebhookOutcome, reason: str) -> dict[str, Any]:
    return {"ok": False, "outcome": outcome.value, "reason": reason, "event": None}


def default_success(parsed: ParsedEvent) -> dict[str, Any]:
    return {
        "ok": True,
        "outcome": WebhookOutcome.ACCEPTED.value,
        "reason": "verified",
        "event": {
            "partner_id": parsed.context.partner_id,
            "delivery_id": parsed.context.delivery_id,
            "event_type": parsed.context.event_type,
        },
    }


def merge_audit_tags(base: dict[str, str], extra: Mapping[str, str]) -> dict[str, str]:
    merged = dict(base)
    for k, v in extra.items():
        merged[str(k)] = str(v)
    return merged


def is_retry_delivery(headers: Mapping[str, str]) -> bool:
    return headers.get("X-Partner-Retry", "").lower() in {"1", "true", "yes"}


def parse_amount_minor_units(payload: Mapping[str, Any]) -> int | None:
    raw = payload.get("amount_minor")
    if raw is None:
        return None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


def validate_currency(payload: Mapping[str, Any]) -> str | None:
    cur = payload.get("currency")
    if cur is None:
        return None
    text = str(cur).strip().upper()
    if len(text) != 3:
        return None
    return text


def attach_processing_hints(parsed: ParsedEvent, hints: Mapping[str, str]) -> ParsedEvent:
    extra = dict(hints)
    extra.setdefault("partner_id", parsed.context.partner_id)
    return ParsedEvent(
        context=WebhookContext(
            partner_id=extra.get("partner_id", parsed.context.partner_id),
