def compute_body_hmac_sha256_hex(body: bytes, secret: bytes) -> str:
    if not secret:
        raise ValueError("secret required")
    digest = hmac.new(secret, body, hashlib.sha256).hexdigest()
    return digest


def normalize_signature_header(raw: str | None) -> str | None:
    if raw is None:
        return None
    text = raw.strip().lower()
    if not text:
        return None
    if text.startswith("sha256="):
        text = text.split("=", 1)[1].strip()
    return text


def timing_safe_sig_equal(expected_hex: str, actual_hex: str) -> bool:
    if not expected_hex or not actual_hex:
        return False
    try:
        expected = bytes.fromhex(expected_hex)
        actual = bytes.fromhex(actual_hex)
    except ValueError:
        return False
    return hmac.compare_digest(expected, actual)


def read_all_bytes(stream: BinaryIO) -> bytes:
    chunks: list[bytes] = []
    while True:
        piece = stream.read(8192)
        if not piece:
            break
        chunks.append(piece)
    return b"".join(chunks)


def verify_hex_signature(body: bytes, secret: bytes, sig_hex: str | None) -> bool:
    if sig_hex is None:
        return False
    expected = compute_body_hmac_sha256_hex(body, secret)
    return timing_safe_sig_equal(expected, sig_hex)


def verify_stream_signature(stream: BinaryIO, secret: bytes, sig_hex: str | None) -> bool:
    raw = read_all_bytes(stream)
    return verify_hex_signature(raw, secret, sig_hex)


