    expected = compute_body_hmac_sha256_hex(body, secret)
    return {
        "expected_prefix": expected[:8],
        "offered_prefix": (offered or "")[:8],
        "body_len": str(len(body)),
    }


def secret_strength_ok(secret: bytes) -> bool:
    return len(secret) >= 16


