import hashlib
import hmac
import io
import json

import pytest

from config import load_webhook_secret
from handler import process_partner_webhook, process_partner_webhook_bytes, verify_only_hex


def _sig(body: bytes, secret: bytes | None = None) -> str:
    s = secret or load_webhook_secret()
    return hmac.new(s, body, hashlib.sha256).hexdigest()


def _payload(**extra: object) -> bytes:
    base = {
        "partner_id": "acme",
        "delivery_id": "dlv-1",
        "event_type": "invoice.paid",
        "amount_minor": 100,
        "currency": "usd",
    }
    base.update(extra)
    return json.dumps(base, separators=(",", ":")).encode("utf-8")


def test_happy_path_verified_webhook_returns_accepted():
    body = _payload()
    headers = {"X-Partner-Signature": _sig(body)}
    out = process_partner_webhook(io.BytesIO(body), headers)
    assert out["ok"] is True
    assert out["outcome"] == "accepted"
    assert out["event"]["delivery_id"] == "dlv-1"


def test_edge_case_bad_signature_rejected():
    body = _payload()
    headers = {"X-Partner-Signature": "0" * 64}
    out = process_partner_webhook(io.BytesIO(body), headers)
    assert out["ok"] is False
    assert out["outcome"] == "invalid_signature"


def test_boundary_sha256_prefix_still_normalized():
    body = _payload()
    sig = _sig(body)
    headers = {"X-Partner-Signature": f"sha256={sig}"}
    out = process_partner_webhook(io.BytesIO(body), headers)
    assert out["ok"] is True


def test_unexpected_input_missing_signature_header():
    body = _payload()
    out = process_partner_webhook(io.BytesIO(body), {})
    assert out["ok"] is False
    assert out["outcome"] == "missing_signature"


def test_unexpected_input_invalid_json_body_after_verification_path():
    body = b"{"
    headers = {"X-Partner-Signature": _sig(body)}
    out = process_partner_webhook(io.BytesIO(body), headers)
    assert out["ok"] is False
    assert out["outcome"] in {"invalid_json", "invalid_signature"}


def test_verify_only_hex_helper_matches_crypto_primitive():
    body = b'{"a":1}'
    secret = load_webhook_secret()
    assert verify_only_hex(body, secret, _sig(body)) is True
    assert verify_only_hex(body, secret, "f" * 64) is False


def test_bytes_helper_matches_stream_path():
    body = _payload(delivery_id="dlv-2")
    headers = {"X-Partner-Signature": _sig(body)}
    out = process_partner_webhook_bytes(body, headers)
    assert out["ok"] is True
    assert out["event"]["delivery_id"] == "dlv-2"


def test_unicode_payload_still_bytes_signed():
    body = json.dumps({"partner_id": "x", "delivery_id": "d", "event_type": "t", "note": "€"}, separators=(",", ":")).encode(
        "utf-8"
    )
    headers = {"X-Partner-Signature": _sig(body)}
    out = process_partner_webhook(io.BytesIO(body), headers)
    assert out["ok"] is True


def test_malformed_signature_length_rejected():
    body = _payload()
    headers = {"X-Partner-Signature": "abc"}
    out = process_partner_webhook(io.BytesIO(body), headers)
    assert out["ok"] is False
    assert out["outcome"] == "invalid_signature"


def test_integration_headers_case_insensitive_signature_key():
    body = _payload(delivery_id="dlv-9")
    headers = {"x-partner-signature": _sig(body)}
    out = process_partner_webhook(io.BytesIO(body), headers)
    assert out["ok"] is True
